import Icon from '@cetus/ui-kit/src/components/Icon'
import { Flex } from '@chakra-ui/react'

type IconBgProps = {
  xlinkHref: string
  svgHover?: string
  svgFill?: string
  onClick?: (e: any) => void
}
export default function IconBg(props: IconBgProps) {
  const { svgHover = 'text_caption', svgFill = 'text_paragraph', xlinkHref, onClick } = props
  return (
    <Flex
      bg="bg_secondary"
      borderRadius="12px"
      w="40px"
      h="40px"
      alignItems="center"
      justifyContent="center"
      border="1px solid"
      borderColor="border"
      cursor="pointer"
      onClick={onClick}
    >
      <Icon svgHover={svgHover} svgFill={svgFill} xlinkHref={xlinkHref} variant="solid" />
    </Flex>
  )
}
