import usePumpTokenListStore from '@/store/pumpTokenList'
import { Box, Grid } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import HomeListItem from './ListItem'
import LoadingItem from './LoadingItem'
export default function HomeListBox({ newCreateToken }: { newCreateToken: any }) {
  const { pumpTokenList, pumpTokenListRefreshLoading, pumpTokenListLordMoreLoading } = usePumpTokenListStore()
  useEffect(() => {
    console.log('🚀 ~ HomeListBox ~ pumpTokenList:', pumpTokenList)
  }, [pumpTokenList])
  const [isAddAnimation, setIsAddAnimation] = useState(false)
  useEffect(() => {
    if (newCreateToken) {
      setIsAddAnimation(true)
      setTimeout(() => {
        setIsAddAnimation(false)
      }, 1000)
    }
    // newCreateToken
  }, [pumpTokenList[0]?.coin_type])
  return (
    <Grid
      w="100%"
      color="text_caption"
      position="relative"
      gap={{
        base: '16px',
        xl: '20px'
      }}
      templateColumns={{
        base: 'repeat(1, 1fr)', // 小屏幕每行1个
        md: 'repeat(2, 1fr)', // 小屏幕每行2个
        lg: 'repeat(3, 1fr)', // 中等屏幕每行3个
        xl: 'repeat(4, 1fr)' // 大屏幕每行4个
      }}
    >
      {pumpTokenListRefreshLoading || pumpTokenListLordMoreLoading
        ? [{}, {}, {}, {}, {}, {}, {}, {}].map((item, index) => {
            return <LoadingItem key={index} />
          })
        : pumpTokenList.map((item, index) => {
            return (
              <Box key={item?.coin_type} className={isAddAnimation && index == 0 ? 'data_animation' : ''}>
                <HomeListItem item={item} />
              </Box>
            )
          })}
    </Grid>
  )
}
