import Bg from '@/assets/images/bg@2x.png'
import img_completed from '@/assets/images/img_completed.png'
import { AddressUnderline } from '@cetus/design'
import TextWrap from '@cetus/ui-kit/src/components/TextWarp'
import { formatNumber, formatPercentage } from '@cetus/utils'
import { Box, HStack, Image, Progress, Text, VStack } from '@chakra-ui/react'
import { useNavigate } from 'react-router-dom'
import TokenImg from '../common/TokenImg'
import { ListItemProps } from './ListItem'

export default function H5ListItem(props: ListItemProps) {
  const { item, market_cap, raising_progress } = props
  const navigate = useNavigate()
  return (
    <Box w="100%" className="home_item" position="relative" p="1px" borderRadius="16px" overflow="hidden">
      <VStack
        gap="14px"
        align="flex-start"
        h="100%"
        backgroundImage={Bg}
        bgColor="bg_secondary"
        backgroundSize="120% 120%"
        backgroundPosition="center"
        position="relative"
        borderRadius="16px"
        p="12px"
        onClick={() => navigate(`/trade/${item?.TokenDetail.coin_type}`)}
      >
        <HStack gap="12px">
          <Box flex="0 0 108px">
            <Box w="100%" aspectRatio={1} margin="auto" position="relative">
              <TokenImg src={item?.TokenDetail.image} imageStyle={{ objectFit: 'cover', borderRadius: '13px' }} />
              {Number(item?.status) >= 2 && (
                <Image
                  src={img_completed}
                  w="100%"
                  h="31px"
                  minW="100%"
                  position="absolute"
                  bottom="-3px"
                  left="50%"
                  transform="translateX(-50%)"
                  objectFit="contain"
                />
              )}
            </Box>
          </Box>
          <VStack align="flex-start" flex="1" justify="space-between" gap="0">
            {/* <PriceChangeBlock priceChange={item?.price_change_24h} /> */}
            <VStack gap="8px" mt="12px" mb="20px">
              <TextWrap textAlign="left" color="text_caption" h="16px" lineHeight="1" fontSize="16px" fontWeight="500">
                {item?.TokenDetail?.name}
              </TextWrap>
              <TextWrap textAlign="left" color="text_paragraph" h="16px" lineHeight="16px" fontSize="12px" fontWeight="500">
                {item?.TokenDetail?.symbol ? `(${item?.TokenDetail?.symbol})` : ''}
              </TextWrap>
            </VStack>
            <HStack w="100%" justify="space-between" h="14px">
              <Text fontSize="14px" color="text_paragraph" lineHeight="14px">
                Creator:
              </Text>
              <AddressUnderline
                address={item?.TokenDetail.creator_address}
                fontSize="14px"
                lineHeight="14px"
                color="text_caption"
                cursor="pointer"
                onClickLink={() => {
                  navigate(`/profile/${item?.TokenDetail.creator_address}`)
                }}
              />
            </HStack>
          </VStack>
        </HStack>

        <VStack w="100%" gap="16px">
          <Box w="100%" p="12px" borderRadius="8px" border="1px solid" borderColor="border" bg="bg_primary">
            <HStack w="100%" justify="space-between">
              <Text fontSize="14px" color="text_paragraph">
                Market Cap:
              </Text>
              <HStack>
                <Text fontSize="14px" color="text_caption" maxW="100px" textAlign="right" whiteSpace="wrap">
                  ${formatNumber(market_cap)}
                </Text>
              </HStack>
            </HStack>
            <HStack w="100%" h="16px" mt="12px">
              <Progress h="6px" value={Number(raising_progress)} w="100%" />
              <Text fontSize="14px">({formatPercentage(Number(raising_progress), 2)})</Text>
            </HStack>
          </Box>
          <Text
            w="100%"
            h="48px"
            lineHeight="16px"
            fontSize="12px"
            color="primary_gray"
            sx={{
              display: '-webkit-box', // 添加 display 属性
              WebkitLineClamp: 3,
              WebkitBoxOrient: 'vertical',
              overflow: 'hidden',
              textOverflow: 'ellipsis'
            }}
          >
            {item?.TokenDetail.description}
          </Text>
        </VStack>
      </VStack>
    </Box>
  )
}
