import { Box, HStack, Input, InputGroup, InputLeftElement } from '@chakra-ui/react';
import Icon from './Icon';

export default function SearchInput(props: { searchText: string; placeholder: string; onChange: (text: string) => void }) {
  const { searchText, onChange, placeholder } = props

  return (
    <HStack w="100%" justifyContent="space-between" position="relative">
      <InputGroup>
        <InputLeftElement justifyContent="center">
          <Icon mt="10px" xlinkHref="#icon-icon_search" marginLeft="10px" />
        </InputLeftElement>
        <Input
          h="40px"
          pl="34px"
          pr="34px"
          placeholder={placeholder}
          variant="outline"
          fontSize="12px"
          borderRadius="full"
          value={searchText}
          onChange={e => {
            onChange(e.target.value)
          }}
        />
      </InputGroup>
      {searchText ? (
        <Box position="absolute" top="10px" right="10px" onClick={() => onChange('')}>
          <Icon xlinkHref="#icon-icon_closure" variant="gray" />
        </Box>
      ) : null}
    </HStack>
  )
}
