import { isPrimaryDomain } from '@/hook/common/usePumpApiDomain'
import usePumpApiDomainStore from '@/store/apiDomain'
import useGlobalToast from '@cetus/hooks/src/useGlobalToast'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { Box } from '@chakra-ui/react'
import { useState } from 'react'

function SwitchApiEgg() {
  const [clickCount, setClickCount] = useState(0)
  const [lastClickTime, setLastClickTime] = useState<Date | null>(null)
  const { showCommonToast } = useGlobalToast()
  const { currentDomain, setCurrentDomain } = usePumpApiDomainStore()

  const handleClick = () => {
    const now = new Date()

    // 如果超过 1 秒未点击，则重置计数
    if (lastClickTime && now.getTime() - lastClickTime.getTime() > 1000) {
      setClickCount(1)
    } else {
      setClickCount(prev => prev + 1)
    }

    setLastClickTime(now)

    // 如果点击次数达到 5 次，触发彩蛋
    if (clickCount + 1 === 5) {
      triggerEgg()
      setClickCount(0) // 重置点击计数
      setLastClickTime(null)
    }
  }

  const triggerEgg = () => {
		console.log("🚀 ~ file: SwitchApiEgg.tsx:38 ~ triggerEgg ~ currentDomain:", currentDomain);
    if (isPrimaryDomain(currentDomain) && envConfigs.pump_api.api_backup_domain) {

      setCurrentDomain(envConfigs.pump_api.api_backup_domain)
      showCommonToast(`Switched to the domain: ${envConfigs.pump_api.api_backup_domain}`, 'success')
    } else {
      setCurrentDomain(envConfigs.pump_api.api_primary_domain)
      showCommonToast(`Switched to the domain: ${envConfigs.pump_api.api_primary_domain}`, 'success')
    }
  }

  return <Box position="absolute" w="150px" h="150px" onClick={handleClick}></Box>
}

export default SwitchApiEgg
