import { IconBg } from '@cetus/design'
import { CheckBox, Icon, RefreshButton, SearchInput } from '@cetus/ui-kit'
import { Box, Flex, HStack, Text } from '@chakra-ui/react'
import { FilterSortBy, sortByType } from './FilterSortBy'

type FilterProps = {
  searchText: string
  sortRule: string
  isChecked: boolean
  currentSort: sortByType
  handleInputChange: (text: string) => void
  handleIsChecked: () => void
  handleChangeSortRule: () => void
  handleChangeSortBy: (item: sortByType) => void
  handleRefresh: () => void
}
export default function HomeListFilter(props: FilterProps) {
  const {
    sortRule,
    searchText,
    isChecked,
    currentSort,
    handleChangeSortBy,
    handleChangeSortRule,
    handleRefresh,
    handleInputChange,
    handleIsChecked
  } = props
  return (
    <HStack
      w="100%"
      justify="space-between"
      flexDirection={{
        base: 'column',
        lg: 'row'
      }}
    >
      <Box
        w={{
          base: '100%',
          lg: '180px',
          xl: '320px'
        }}
        position="relative"
        sx={{
          '.chakra-input': {
            fontSize: '14px',
            borderRadius: '12px !important'
          }
        }}
      >
        <SearchInput searchText={searchText} onChange={handleInputChange} placeholder="Search for token" />
        {searchText ? (
          <Box position="absolute" top="10px" right="10px" onClick={() => handleInputChange('')}>
            <Icon xlinkHref="#icon-icon_close" variant="gray" />
          </Box>
        ) : null}
      </Box>

      <HStack
        w={{
          base: '100%',
          lg: 'unset'
        }}
        gap="8px"
        flexDirection={{
          base: 'column',
          lg: 'row'
        }}
      >
        <Flex
          p="12px"
          bg="bg_secondary"
          borderRadius="12px"
          h="40px"
          align="center"
          border="1px solid"
          borderColor="border"
          sx={{
            _hover: {
              p: {
                color: 'text_caption'
              }
            }
          }}
          w={{
            base: '100%',
            lg: 'unset'
          }}
        >
          <CheckBox checked={isChecked} onClick={handleIsChecked} />
          <Text ml="10px" color={isChecked ? 'text_caption' : 'text_paragraph'}>
            Listed on Cetus DEX
          </Text>
        </Flex>
        <HStack
          w={{
            base: '100%',
            lg: 'unset'
          }}
        >
          <FilterSortBy currentSort={currentSort} onSortByChange={(item: sortByType) => handleChangeSortBy(item)} />
          <HStack>
            <IconBg xlinkHref={sortRule == 'desc' ? '#icon-icon_sort2' : '#icon-icon_sort_asc1'} onClick={handleChangeSortRule} />
            <RefreshButton handleRefresh={handleRefresh} />
          </HStack>
        </HStack>
      </HStack>
    </HStack>
  )
}
