import { usePumpTokenHelper } from '@/hook/pump/usePumpTokenHelper'
import { PumpToken } from '@/type/pump'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import H5ListItem from './H5ListItem'
import PCListItem from './PCListItem'

export interface ListItemProps {
  item: PumpToken
  market_cap?: string
  raising_progress?: string
}
export default function HomeListItem(props: { item: PumpToken }) {
  const { item } = props
  const { isApp } = useWindowWidth()
  const { market_cap, raising_progress } = usePumpTokenHelper(item)
  return isApp ? (
    <H5ListItem item={item} market_cap={market_cap} raising_progress={raising_progress} />
  ) : (
    <PCListItem item={item} market_cap={market_cap} raising_progress={raising_progress} />
  )
}
