import SwitchApiEgg from '@/components/common/SwitchApiEgg'
import HomeBanner from '@/components/home/Banner'
import { sortByType } from '@/components/home/FilterSortBy'
import HomeListBox from '@/components/home/ListBox'
import HomeListFilter from '@/components/home/ListFilter'
import { usePumpTokenList } from '@/hook/pump'
import useEventStore from '@/store/event'
import usePumpTokenListStore from '@/store/pumpTokenList'
import { useInterval } from '@cetus/hooks'
import { useDebounceFunction } from '@cetus/hooks/src/useDebounce'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import useGlobalStore from '@cetus/stores/src/global'
import { NoData, Pagination } from '@cetus/ui-kit'
import { Center, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

export default function HomePage() {
  const { setIsScrollTop } = useGlobalStore()
  const { fetchPumpTokenList, isLoadMoreError } = usePumpTokenList()
  const { popHomeAnimEvent } = useEventStore()
  const { maxPage, pumpTokenList, pumpTokenListRefreshLoading, pumpTokenListLordMoreLoading, hasMoreData } = usePumpTokenListStore()
  const [newCreateToken, setNewCreateToken] = useState<any>(null)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize, setPageSize] = useState(40)
  const [searchText, setSearchText] = useState<string>('')
  const [enterPageTime, setEnterPageTime] = useState<number>(0)
  const { windowWidth } = useWindowWidth()
  const handleInputChange = async (text: string) => {
    setCurrentPage(1)
    setNewCreateToken(null)
    setSearchText(text)
    debouncedSearchText({ page: 1, query_filter_value: text })
  }

  const [sortRule, setSortRule] = useState('desc')
  const [currentSort, setCurrentSortBy] = useState<sortByType>({
    label: 'Launched Time',
    value: 'time'
  })
  const handleChangeSortRule = () => {
    console.log('🚀 ~ handleChangeSortRule ~ sortRule:', sortRule)
    setNewCreateToken(null)
    const current = sortRule == 'desc' ? 'asc' : 'desc'
    fetchList({ page: 1, rule: current })
    setSortRule(current)
    setCurrentPage(1)
  }

  const handleChangeSortBy = (item: sortByType) => {
    console.log('🚀 ~ handleChangeSortBy ~ item:', item)
    if (item.value !== currentSort.value) {
      setNewCreateToken(null)
      fetchList({ page: 1, rule: 'desc', order_by_type: item.value })
      setCurrentSortBy(item)
      setCurrentPage(1)
      setSortRule('desc')
    }
  }

  const [isChecked, setIsChecked] = useState(false)
  const handleIsChecked = () => {
    setNewCreateToken(null)
    setCurrentPage(1)
    fetchList({ page: 1, if_on_dex: !isChecked })
    console.log('🚀 ~ handleIsChecked ~ isChecked:', isChecked)
    setIsChecked(!isChecked)
  }

  const handleRefresh = () => {
    console.log('handleRefresh')
    fetchList({ page: 1 })
    setCurrentPage(1)
  }

  const clickLoadMore = (current: number) => {
    setNewCreateToken(null)
    setIsScrollTop(true)
    setTimeout(() => {
      setIsScrollTop(false)
    }, 1000)

    fetchList({ page: current })
    setCurrentPage(current)
  }
  useInterval({
    interval: 4000,
    callback: () => {
      const event = popHomeAnimEvent()
      console.log('🚀 ~ file: Home.tsx:22 ~ useInterval ~ event:', enterPageTime, event)
      if (
        event &&
        newCreateToken &&
        event?.coin_type !== newCreateToken?.coin_type &&
        event.timestamp > enterPageTime &&
        currentSort.value == 'time' &&
        currentPage == 1 &&
        searchText == '' &&
        sortRule == 'desc' &&
        !isChecked
      ) {
        fetchList({ isNotLoading: true })
        setNewCreateToken(event)
      }
    }
  })
  interface FetchListProps {
    page?: number
    page_size?: number
    rule?: string
    order_by_type?: sortByType['value']
    query_filter_value?: string
    if_on_dex?: boolean
    isNotLoading?: boolean
  }
  const fetchList = ({
    page = currentPage,
    page_size = pageSize,
    rule = sortRule,
    order_by_type = currentSort.value,
    query_filter_value = searchText,
    if_on_dex = isChecked,
    isNotLoading = false
  }: FetchListProps) => {
    const query = if_on_dex
      ? {
          page,
          page_size,
          if_asc: rule == 'asc',
          order_by_type,
          query_filter_value,
          if_on_dex
        }
      : {
          page,
          page_size,
          if_asc: rule == 'asc',
          order_by_type,
          query_filter_value
        }
    if (isNotLoading) {
      fetchPumpTokenList(query)
    } else {
      fetchPumpTokenList(query, true)
    }
  }
  const debouncedSearchText = useDebounceFunction(fetchList, 500)
  useEffect(() => {
    const time = Math.floor(Date.now() / 1000)
    console.log('🚀 ~ useEffect ~ time:', time)
    setEnterPageTime(time)
    // fetchList({})
  }, [])

  useEffect(() => {
    if (windowWidth >= 1200) {
      setPageSize(40)
    } else if (windowWidth >= 810) {
      setPageSize(30)
    } else if (windowWidth >= 500) {
      setPageSize(40)
    } else {
      setPageSize(20)
    }
  }, [windowWidth])

  useEffect(() => {
    fetchList({ page: currentPage })
  }, [pageSize])

  return (
    <VStack w="100%" maxW="1240px" zIndex="1">
      <VStack w="100%" gap="20px">
        <SwitchApiEgg />
        <HomeBanner />
        <HomeListFilter
          sortRule={sortRule}
          searchText={searchText}
          isChecked={isChecked}
          currentSort={currentSort}
          handleInputChange={text => handleInputChange(text)}
          handleIsChecked={handleIsChecked}
          handleChangeSortRule={handleChangeSortRule}
          handleChangeSortBy={item => handleChangeSortBy(item)}
          handleRefresh={handleRefresh}
        />
        {!pumpTokenListRefreshLoading && !isLoadMoreError && pumpTokenList.length == 0 ? (
          <NoData type="nodata" text={searchText.length > 0 ? 'Nothing found...' : 'No Data'} />
        ) : (
          <HomeListBox newCreateToken={newCreateToken} />
        )}
        {!isLoadMoreError && !pumpTokenListRefreshLoading && pumpTokenList.length > 0 && (
          <Center mt="16px">
            <Pagination
              total={pageSize * maxPage}
              size={pageSize}
              currentPage={currentPage}
              onChange={current => {
                clickLoadMore(current)
              }}
            />
          </Center>
          // <Button
          //   w="172px"
          //   h="32px"
          //   fontSize="12px"
          //   borderRadius="8px"
          //   bg="button_ghost_bg"
          //   color="primary"
          //   borderColor="border"
          //   variant="outline"
          //   onClick={clickLoadMore}
          // >
          //   {pumpTokenListLordMoreLoading ? <Spinner /> : 'Load More'}
          // </Button>
        )}
        {/* {!pumpTokenListRefreshLoading && !isLoadMoreError && !hasMoreData && pumpTokenList.length > 0 && (
          <Text fontSize="12px">You’ve reached the end of the list</Text>
        )} */}
        {!pumpTokenListRefreshLoading && isLoadMoreError && <Text fontSize="12px">Something went wrong... </Text>}
      </VStack>
    </VStack>
  )
}
