import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Icon } from '@cetus/ui-kit'
import { Box, Button, HStack, Menu, MenuButton, MenuList, Text } from '@chakra-ui/react'
import { useRef, useState } from 'react'

export type sortByType = {
  label: 'Launched Time' | 'Trading Volume (24H)' | 'Market Cap' | '24H Price Increase'
  value: 'time' | 'volume24h' | 'marketcap' | 'price24h'
}
type PoolsFilterProps = {
  currentSort?: sortByType
  onSortByChange: (type: sortByType) => void
}

export function FilterSortBy(props: PoolsFilterProps) {
  const { currentSort, onSortByChange } = props
  const [isOpen, setIsOpen] = useState(false)
  const btnRef = useRef<HTMLButtonElement>(null)

  const { isApp } = useWindowWidth()

  const sortByList: sortByType[] = [
    {
      label: 'Launched Time',
      value: 'time'
    },
    {
      label: 'Trading Volume (24H)',
      value: 'volume24h'
    },
    {
      label: 'Market Cap',
      value: 'marketcap'
    }
    // {
    //   label: '24H Price Increase',
    //   value: 'price24h'
    // }
  ]
  return (
    <Menu
      isOpen={isOpen}
      onClose={() => {
        setIsOpen(false)
      }}
    >
      <MenuButton
        ref={btnRef}
        w={{
          base: '100%',
          lg: '280px'
        }}
        isActive={isOpen}
        as={Button}
        bg="bg_secondary"
        borderRadius="12px"
        border="1px solid"
        borderColor="border"
        h="40px"
        p="0px 10px"
        sx={{
          _hover: {
            bg: 'bg_secondary',
            '.drop-icon': {
              svg: {
                fill: 'text_caption'
              }
            }
          },
          _active: {
            bg: 'bg_secondary'
          }
        }}
        onClick={() => {
          setIsOpen(true)
        }}
      >
        <HStack align="center" justifyContent="space-between">
          <HStack gap="8px">
            <Icon xlinkHref="#icon-icon_type" variant="gray" />
            <Text color="text_paragraph">{isApp ? 'Sort' : 'Sort by'}</Text>
          </HStack>
          <HStack gap="8px">
            <Text color="text_caption">{currentSort?.label}</Text>
            <Box className="drop-icon">
              <Icon
                svgW="16px"
                xlinkHref="#icon-icon_arrow"
                variant="gray"
                transition="transform 0.5s"
                transform={isOpen ? 'rotate(180deg)' : 'rotate(0deg)'}
              />
            </Box>
          </HStack>
        </HStack>
      </MenuButton>
      <MenuList w={{ base: btnRef?.current?.clientWidth, lg: '280px' }} p="0" opacity="1" overflow="hidden">
        {sortByList.map((item: any) => {
          return (
            <Text
              sx={{
                _hover: {
                  bg: 'card_bg'
                }
              }}
              h="45px"
              lineHeight="45px"
              textAlign="center"
              color="text_caption"
              key={item.value}
              cursor="pointer"
              onClick={() => onSortByChange(item)}
            >
              {item.label}
            </Text>
          )
        })}
      </MenuList>
    </Menu>
  )
}
